const { ApolloServer, gql } = require('@apollo/server');
const { startStandaloneServer } = require('@apollo/server/standalone');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key';

const users = [
  { id: '1', email: 'admin@corp.io', passwordHash: bcrypt.hashSync('admin123', 10), role: 'ADMIN' },
  { id: '2', email: 'user@corp.io', passwordHash: bcrypt.hashSync('userpass', 10), role: 'USER' },
  { id: '3', email: 'service@corp.io', passwordHash: bcrypt.hashSync('svc-token', 10), role: 'SERVICE' }
];

const typeDefs = gql`
  enum Role { USER ADMIN SERVICE }
  type User { id: ID!, email: String!, role: Role! }
  type AuthPayload { token: String!, user: User! }
  type Query {
    me: User
    users: [User!]!
  }
  type Mutation {
    login(email: String!, password: String!): AuthPayload!
    updateRole(userId: ID!, newRole: Role!): User!
    refreshToken(token: String!): AuthPayload!
  }
`;

const resolvers = {
  Query: {
    me: (_, __, { user }) => user,
    users: (_, __, { user }) => {
      if (!user || user.role !== 'ADMIN') throw new Error('Unauthorized');
      return users.map(u => ({ id: u.id, email: u.email, role: u.role }));
    }
  },
  Mutation: {
    login: async (_, { email, password }) => {
      const user = users.find(u => u.email === email);
      if (!user || !await bcrypt.compare(password, user.passwordHash)) {
        throw new Error('Invalid credentials');
      }
      const token = jwt.sign({ userId: user.id, role: user.role }, JWT_SECRET, { expiresIn: '1h' });
      return { token, user: { id: user.id, email: user.email, role: user.role } };
    },
    updateRole: (_, { userId, newRole }, { user }) => {
      if (!user || user.role !== 'ADMIN') throw new Error('Unauthorized');
      const target = users.find(u => u.id === userId);
      if (!target) throw new Error('User not found');
      target.role = newRole;
      return { id: target.id, email: target.email, role: target.role };
    },
    refreshToken: (_, { token: oldToken }) => {
      try {
        // VULNERABILITY: accepts expired tokens and re-signs with arbitrary claims
        // The verify call uses ignoreExpiration, and the decoded payload
        // is directly re-signed without validating against the user store
        const decoded = jwt.verify(oldToken, JWT_SECRET, { ignoreExpiration: true });
        // An attacker can craft a token with role: ADMIN using a leaked/expired
        // token, then refresh it to get a valid ADMIN token
        const newToken = jwt.sign(
          { userId: decoded.userId, role: decoded.role },
          JWT_SECRET,
          { expiresIn: '1h' }
        );
        const user = users.find(u => u.id === decoded.userId);
        if (!user) throw new Error('User not found');
        // Returns fresh token with whatever role was in the OLD token
        // Does NOT check if user's current role matches
        return { token: newToken, user: { id: user.id, email: user.email, role: decoded.role } };
      } catch (e) {
        throw new Error('Invalid token');
      }
    }
  }
};

const server = new ApolloServer({ typeDefs, resolvers });

startStandaloneServer(server, {
  listen: { port: 4000 },
  context: async ({ req }) => {
    const auth = req.headers.authorization || '';
    if (auth.startsWith('Bearer ')) {
      try {
        const token = auth.slice(7);
        const decoded = jwt.verify(token, JWT_SECRET);
        const user = users.find(u => u.id === decoded.userId);
        return { user: user ? { ...user, role: decoded.role } : null };
      } catch { return { user: null }; }
    }
    return { user: null };
  }
}).then(({ url }) => console.log(`Server ready at ${url}`));
